package org.xar.ck3.control.wave2.military.combatwire.phaseevent;

import static org.xar.ck3.control.wave2.military.combatwire.phaseevent.PhaseJson.*;
import static org.xar.ck3.control.wave2.military.combatwire.phaseevent.PhaseConstants.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.TreeSet;
import org.xar.ck3.control.wave2.military.combatwire.PhaseEventRuntime;

/** Complete pinned offline AST runtime. Structural coverage never asserts native effect fidelity. */
public final class StockPhaseEventRuntime implements PhaseEventRuntime {
    public record TrialStep(String eventKey,List<Integer> draws){public TrialStep{Objects.requireNonNull(eventKey);draws=List.copyOf(draws);}}
    private final StockPhaseManifest manifest;
    private final ObjectNode audit;
    public StockPhaseEventRuntime(){this(StockPhaseManifest.load());}
    public StockPhaseEventRuntime(Path path){this(StockPhaseManifest.load(path));}
    private StockPhaseEventRuntime(StockPhaseManifest manifest){this.manifest=manifest;require(digest(evaluatorContract()).equals(EVALUATOR_SHA),"evaluator semantic contract SHA drifted");audit=buildAudit();}
    @Override public String manifestSha256(){return manifest.canonicalSha256();}
    @Override public Set<String> requiredStateRefs(){return manifest.requiredStateRefs();}
    public List<StockPhaseManifest.Source> sourcePins(){return manifest.sources();}
    public ObjectNode audit(){return audit.deepCopy();}
    private ObjectNode buildAudit(){Set<String> direct=new HashSet<>();ArrayNode occurrences=arr(),rows=arr();ObjectNode effectEvents=obj();for(JsonNode e:FEEDBACK)effectEvents.putArray(e.textValue());int totalNodes=0,commanders=0,knights=0;
        for(StockPhaseManifest.Row row:manifest.rows){if(row.type.equals("commander"))commanders++;else knights++;int v=PhaseAst.auditValue(row.validity,row.dependencies),c=PhaseAst.auditValue(row.chance,row.dependencies),e=PhaseAst.auditEffect(row.effect,row.dependencies,direct);totalNodes+=v+c+e;collect(row.effect,row.key,row.key+".effect_ast",occurrences,effectEvents);ObjectNode r=obj().put("global_load_index",row.index).put("type_load_index",row.typeIndex).put("key",row.key).put("type",row.type).put("validity_ast_sha256",digest(row.validity)).put("chance_ast_sha256",digest(row.chance)).put("effect_ast_sha256",digest(row.effect)).put("validity_node_count",v).put("chance_node_count",c).put("effect_node_count",e).put("validity_covered",true).put("chance_covered",true).put("effect_covered",true);rows.add(r);}
        require(commanders==4&&knights==9,"event families drifted");require(direct.equals(strings(DIRECT,"direct")),"direct transition handler coverage drifted");require(!occurrences.isEmpty(),"missing candidate algorithm occurrences");ArrayNode ledger=arr();for(JsonNode name:FEEDBACK){String key=name.textValue();ArrayNode events=array(effectEvents.get(key),key);require(!events.isEmpty(),"feedback effect inventory drifted: "+key);ObjectNode row=object(FEEDBACK_EVIDENCE.get(key),"feedback evidence").deepCopy().put("effect",key).put("model_status","record_only_not_state_complete").put("battle_horizon_exclusion_proved",false).put("feedback_ready",false);row.set("event_keys_source_order",events.deepCopy());ledger.add(row);}
        ObjectNode out=obj().put("schema_version",1).put("status","structurally_covered_fidelity_blocked").put("evaluator_version",VERSION).put("evaluator_sha256",EVALUATOR_SHA).put("manifest_sha256",manifestSha256());ObjectNode scope=out.putObject("scope_semantics").put("root","observed_character").put("combat_side","observed_side_index");scope.set("owner",absent());out.putObject("arithmetic").put("scale",100000).put("signed",true).put("rounding","truncate_toward_zero_after_each_operation");out.putObject("source_order").put("event_rows",true).put("candidate_rows",false).put("candidate_algorithm",true).put("random_list_branches",true);ObjectNode order=out.putObject("candidate_materialization_and_order").put("policy",NATIVE_ORDER).put("candidate_source_proof_policy",PROOF_POLICY).put("manifest_order_policy",MANIFEST_ORDER);order.set("native_source_contract",NATIVE_CONTRACT.deepCopy());order.put("occurrence_count",occurrences.size());order.set("occurrences",occurrences);order.put("algorithm_ready",true).put("materialization_input_ready",false).put("materialization_input_blocker","production_candidate_source_proof_payload_required").put("ready",false);ObjectNode feedback=out.putObject("battle_horizon_feedback").put("effect_count",ledger.size()).put("ready",false);feedback.set("effects",ledger);ObjectNode coverage=out.putObject("coverage").put("event_row_count",rows.size()).put("commander_row_count",commanders).put("knight_row_count",knights).put("ast_node_count",totalNodes).put("trigger_ast_rows_covered",rows.size()).put("chance_ast_rows_covered",rows.size()).put("effect_ast_rows_covered",rows.size()).put("direct_transition_count",direct.size()).put("internal_transition_count",INTERNAL.size());coverage.putArray("unsupported_nodes");coverage.putArray("unsupported_effects");coverage.put("structural_ready",true).put("ready",false);out.set("rows",rows);out.put("ast_evaluator_ready",false).put("original_trace_ready",false);seal(out,"proof_sha256");return out;
    }
    private static void collect(JsonNode node,String event,String path,ArrayNode occurrences,ObjectNode effectEvents){if(node.isObject()){String op=node.path("op").asText();if(op.equals("select_side_knight")){require(node.path("order_policy").asText().equals(MANIFEST_ORDER),"manifest order policy drifted");occurrences.add(obj().put("event_key",event).put("node_path",path).put("manifest_order_policy",MANIFEST_ORDER).put("evaluator_order_policy",NATIVE_ORDER));}else if(op.equals("call_transition")&&node.path("key").asText().equals("observational_only")){for(JsonNode e:array(node.path("args").get("effects"),"feedback effects")){String name=text(e,"effect");require(effectEvents.has(name),"unaccounted feedback "+name);unique(array(effectEvents.get(name),name),event);}}node.properties().forEach(e->{if(!e.getKey().equals("op"))collect(e.getValue(),event,path+"."+e.getKey(),occurrences,effectEvents);});}else if(node.isArray())for(int i=0;i<node.size();i++)collect(node.get(i),event,path+"["+i+"]",occurrences,effectEvents);}
    private ObjectNode common(String status){return obj().put("schema_version",1).put("status",status).put("evaluator_version",VERSION).put("evaluator_sha256",EVALUATOR_SHA).put("evaluator_proof_sha256",text(audit.get("proof_sha256"),"proof sha")).put("manifest_sha256",manifestSha256());}
    private static ObjectNode proofProjection(PhaseTrialState state){ObjectNode out=obj();for(String key:List.of("policy","source_vector_equivalence","sequence_sha256"))out.set(key,state.proof.get(key).deepCopy());return out;}
    @Override public ObjectNode evaluateContexts(ArrayNode validatedContexts){Objects.requireNonNull(validatedContexts);ArrayNode contexts=arr(),proofs=arr();for(JsonNode context:validatedContexts){PhaseTrialState s=new PhaseTrialState(context,null);ObjectNode row=obj().put("root_character_id",s.rootId).put("combat_side_index",s.side).put("enemy_side_index",s.enemy);ArrayNode roles=row.putArray("phase_roles");s.roles.forEach(roles::add);row.set("owner_scope",absent());row.set("candidate_source_proof",proofProjection(s));row.put("candidate_materialization_input_ready",true);ArrayNode rows=row.putArray("rows");for(StockPhaseManifest.Row event:manifest.rows)rows.add(PhaseAst.evaluateRow(event,s));contexts.add(row);ObjectNode proof=proofProjection(s);proof.put("enemy_side_index",s.enemy);proofs.add(proof);}boolean materialization=!contexts.isEmpty();ObjectNode order=object(audit.get("candidate_materialization_and_order"),"candidate audit").deepCopy().put("materialization_input_ready",materialization).put("ready",materialization);if(materialization)order.putNull("materialization_input_blocker");else order.put("materialization_input_blocker","production_candidate_source_proof_payload_required");order.set("production_proofs",proofs);ObjectNode out=common("structurally_covered_fidelity_blocked").put("scope","hypothetical_precontact_root_plus_combat_side_owner_absent");out.set("event_row_coverage",audit.get("coverage").deepCopy());out.set("candidate_materialization_and_order",order);out.set("battle_horizon_feedback",audit.get("battle_horizon_feedback").deepCopy());out.put("context_count",contexts.size());out.set("contexts",contexts);out.put("ast_evaluator_ready",false).put("original_trace_ready",false);seal(out,"projection_sha256");return out;}
    public ObjectNode evaluateReachableFeedback(ArrayNode contexts){ObjectNode projection=evaluateContexts(contexts);Set<String> reachable=new TreeSet<>();for(JsonNode context:projection.get("contexts"))for(JsonNode row:context.get("rows"))if(bool(row.get("trigger_valid"),"trigger")&&signed(row.get("selectable_int_weight"),"weight")>0)reachable.add(text(row.get("key"),"event key"));ArrayNode effects=arr();int count=0;for(JsonNode source:projection.path("battle_horizon_feedback").get("effects")){ObjectNode effect=obj();effect.set("effect",source.get("effect").deepCopy());ArrayNode keys=effect.putArray("positive_weight_event_keys");for(JsonNode key:source.get("event_keys_source_order"))if(reachable.contains(key.textValue()))keys.add(key.deepCopy());if(!keys.isEmpty())count++;effects.add(effect);}ObjectNode out=obj().put("schema_version",1).put("status","initial_frame_positive_weight_possibility_only").put("manifest_sha256",manifestSha256()).put("projection_sha256",projection.path("projection_sha256").asText()).put("context_count",contexts.size());ArrayNode keys=out.putArray("positive_weight_event_keys");reachable.forEach(keys::add);out.set("potential_unresolved_effects",effects);out.put("potential_unresolved_effect_count",count).put("future_eligibility_may_change",true).put("planner_usable",false).put("active_attack_allowed",false);seal(out,"result_sha256");return out;}
    private StockPhaseManifest.Row event(String key){require(key!=null&&!key.isEmpty(),"empty event key");for(StockPhaseManifest.Row row:manifest.rows)if(row.key.equals(key))return row;throw new IllegalArgumentException("unknown phase-event row "+key);}
    public ObjectNode executeEffect(JsonNode context,String eventKey,List<Integer> draws,JsonNode advantageModel,boolean requireValid){StockPhaseManifest.Row row=event(eventKey);PhaseTrialState s=new PhaseTrialState(context,advantageModel);ObjectNode evaluation=PhaseAst.evaluateRow(row,s);require(s.roles.contains(row.type),"root has no "+row.type+" role");require(!requireValid||bool(evaluation.get("trigger_valid"),"trigger"),"phase-event row is not valid");ObjectNode before=s.snapshot();PhaseDrawTape tape=new PhaseDrawTape(draws);PhaseAst.execute(row.effect,s,tape,row.key+".effect_ast");ObjectNode out=common("offline_projection_applied_fidelity_blocked"),event=out.putObject("event");for(String key:List.of("global_load_index","type_load_index","key","type","trigger_valid","chance_raw","int_weight"))event.set(key,evaluation.get(key).deepCopy());out.set("draw_tape",tape.toJson());out.set("before_state_sha256",before.get("state_sha256").deepCopy());out.set("after_state",s.snapshot());out.set("transition_log",s.log.deepCopy());out.put("candidate_selection_algorithm_ready",true).put("candidate_materialization_input_ready",true).put("candidate_materialization_and_order_ready",true).put("battle_horizon_feedback_ready",false).put("ast_evaluator_ready",false).put("original_trace_ready",false).put("planner_usable",false).put("active_attack_allowed",false);seal(out,"result_sha256");return out;}
    public ObjectNode executeEffect(JsonNode context,String eventKey,List<Integer> draws){return executeEffect(context,eventKey,draws,null,true);}
    public ObjectNode executeTrialSequence(JsonNode context,List<TrialStep> steps,JsonNode advantageModel){PhaseTrialState s=new PhaseTrialState(context,advantageModel);ObjectNode out=common("ordered_offline_trial_projection_fidelity_blocked").put("root_character_id",s.rootId);out.set("initial_state_sha256",s.snapshot().get("state_sha256").deepCopy());ArrayNode results=out.putArray("steps");for(TrialStep step:List.copyOf(steps)){StockPhaseManifest.Row row=event(step.eventKey);ObjectNode evaluation=PhaseAst.evaluateRow(row,s);require(bool(evaluation.get("trigger_valid"),"trigger"),"phase-event row is invalid at trial step "+results.size());JsonNode before=s.snapshot().get("state_sha256").deepCopy();int previous=s.log.size();PhaseDrawTape tape=new PhaseDrawTape(step.draws);PhaseAst.execute(row.effect,s,tape,row.key+".effect_ast");require(tape.position==tape.draws.size(),"trial step has unused draws; RNG boundary ambiguous");ObjectNode result=obj().put("ordinal",results.size()).put("event_key",step.eventKey).put("draw_count",tape.position);result.set("before_state_sha256",before);result.set("after_state_sha256",s.snapshot().get("state_sha256").deepCopy());ArrayNode logs=result.putArray("transition_log");for(int i=previous;i<s.log.size();i++)logs.add(s.log.get(i).deepCopy());results.add(result);}out.set("final_state",s.snapshot());out.put("battle_horizon_feedback_ready",false).put("original_trace_ready",false).put("planner_usable",false).put("active_attack_allowed",false);seal(out,"result_sha256");return out;}
}

